parameters.jsCode:
const TZ_OFFSET_MS = 3 * 60 * 60 * 1000; // Asia/Riyadh, UTC+3, no DST

const events = $input.all().map(i => i.json);
const busy = events
  .filter(e => e.status !== 'cancelled' && e.start && e.start.dateTime && e.end && e.end.dateTime)
  .map(e => ({ start: new Date(e.start.dateTime).getTime(), end: new Date(e.end.dateTime).getTime() }));

const SLOT_MIN = 30;
const DAY_START_H = 9;
const DAY_END_H = 17;

let slotStartMs = null;
const now = new Date();
const nowRiyadh = new Date(now.getTime() + TZ_OFFSET_MS);

for (let dayOffset = 1; dayOffset <= 10 && slotStartMs === null; dayOffset++) {
  const dayRiyadh = new Date(Date.UTC(nowRiyadh.getUTCFullYear(), nowRiyadh.getUTCMonth(), nowRiyadh.getUTCDate() + dayOffset));
  const weekday = dayRiyadh.getUTCDay(); // 0=Sun .. 5=Fri, 6=Sat (Saudi weekend)
  if (weekday === 5 || weekday === 6) continue;
  for (let mins = DAY_START_H * 60; mins < DAY_END_H * 60; mins += SLOT_MIN) {
    const candStartRiyadhMs = dayRiyadh.getTime() + mins * 60000;
    const candStartUtcMs = candStartRiyadhMs - TZ_OFFSET_MS;
    const candEndUtcMs = candStartUtcMs + SLOT_MIN * 60000;
    const overlaps = busy.some(b => candStartUtcMs < b.end && candEndUtcMs > b.start);
    if (!overlaps) { slotStartMs = candStartUtcMs; break; }
  }
}

const page = $('Look Up Candidate').first().json;
const props = (page && page.properties) || {};
const name = (props['Candidate Name'] && props['Candidate Name'].title && props['Candidate Name'].title[0] && props['Candidate Name'].title[0].plain_text) || '';
const email = (props['Email'] && props['Email'].email) || '';
const jobTitle = (props['Target Job Title'] && props['Target Job Title'].rich_text && props['Target Job Title'].rich_text[0] && props['Target Job Title'].rich_text[0].plain_text) || '';
const client = (props['Client'] && props['Client'].rich_text && props['Client'].rich_text[0] && props['Client'].rich_text[0].plain_text) || '';

return [{
  json: {
    found: slotStartMs !== null,
    slotStartIso: slotStartMs !== null ? new Date(slotStartMs).toISOString() : null,
    slotEndIso: slotStartMs !== null ? new Date(slotStartMs + SLOT_MIN * 60000).toISOString() : null,
    candidateName: name,
    candidateEmail: email,
    targetJobTitle: jobTitle,
    client: client
  }
}];
